<script setup lang="ts">
defineProps<{enabled:boolean;consent:boolean;preview:string;hasContext:boolean;busy:boolean;message:string;error:string}>()
defineEmits<{ 'update:enabled':[value:boolean];'update:consent':[value:boolean];choose:[file:File|undefined];check:[] }>()
</script>
<template><section class="image-input"><label><input type="checkbox" :checked="enabled" :disabled="busy" @change="$emit('update:enabled',($event.target as HTMLInputElement).checked)">图片＋自然语言（现有DeepSeek）</label><div v-if="enabled"><p>{{ message }} <button :disabled="busy" @click="$emit('check')">重新检测</button></p><label>上传PNG/JPEG（≤2MiB）<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="$emit('choose',($event.target as HTMLInputElement).files?.[0])"></label><img v-if="preview" :src="preview" alt="当前看图会话的图片预览"><p v-if="hasContext">可以继续追问同一张图；换图会开始新的图片上下文。服务重启或20分钟过期需重新上传。</p><label><input type="checkbox" :checked="consent" :disabled="busy" @change="$emit('update:consent',($event.target as HTMLInputElement).checked)">允许本次图片、问题和最近三轮看图问答发送至DeepSeek，会产生API费用</label><p>例如：“这张图有哪些疑似漂浮物？”“重点检查左下角”“哪些目标还不确定？”</p><p>结果为视觉模型候选观察。需要YOLO检测框时，可进入环境发现的上传检测；不会自动创建事件或执行任务。</p><p v-if="error" role="alert">{{ error }}</p></div></section></template>
